//! Configuration for `forge coverage`.

use clap::ValueEnum;
use semver::{Version, VersionReq};
use serde::{Deserialize, Deserializer, Serialize};
use std::path::PathBuf;

/// Coverage report kinds that can be generated by `forge coverage`.
///
/// Used both as a CLI value (`--report <kind>`) and as a TOML configuration
/// value under `[profile.<name>.coverage] report = ["..."]`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize, ValueEnum)]
#[serde(rename_all = "lowercase")]
pub enum CoverageReportKind {
    #[default]
    Summary,
    Lcov,
    Debug,
    Bytecode,
    /// JSON report mapping each test to the source items it covers.
    Attribution,
    /// JSON report listing uncovered source items with their location and context.
    Gaps,
}

/// Configuration for `forge coverage`, exposed under `[coverage]` and
/// `[profile.<name>.coverage]` in `foundry.toml`.
///
/// Fields here mirror the CLI flags accepted by `forge coverage`. CLI flags
/// take precedence over configuration values when both are provided.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct CoverageConfig {
    /// Report kinds that `forge coverage` generates.
    ///
    /// The `--report` flag, which can be repeated, replaces this list. Valid values:
    ///
    /// - `summary`: prints a coverage summary table.
    /// - `lcov`: writes an LCOV tracefile to `lcov.info`; see `lcov_version`.
    /// - `debug`: prints a verbose report of every coverage item, for debugging coverage itself.
    /// - `bytecode`: writes annotated per-contract bytecode coverage to `bytecode-coverage/`.
    /// - `attribution`: writes `coverage-attribution.json`, mapping each test to the source items
    ///   it covers.
    /// - `gaps`: writes `coverage-gaps.json`, listing uncovered source items with their location
    ///   and context.
    #[serde(default = "default_report_kinds")]
    pub report: Vec<CoverageReportKind>,

    /// Version of the LCOV tracefile format used by the `lcov` report.
    ///
    /// The value is a string in the format `MAJOR[.MINOR]`, such as `"1"` or `"2.2"`; pre-release
    /// versions are rejected. The `--lcov-version` flag overrides it. Main differences:
    ///
    /// - `1.x`: the original v1 format.
    /// - `2.0`: adds "line end" numbers for functions.
    /// - `2.2`: changes the format of functions.
    #[serde(default = "default_lcov_version", deserialize_with = "deserialize_lcov_version")]
    pub lcov_version: Version,

    /// Whether to compile with `viaIR` and minimum optimization, as a workaround for "stack too
    /// deep" errors.
    ///
    /// By default `forge coverage` disables the optimizer and `viaIR` for accurate source maps.
    /// This setting enables `viaIR` with minimum optimization instead, which fixes most "stack too
    /// deep" errors at the cost of less accurate source mappings, so use it only when you need
    /// it. The `--ir-minimum` flag also enables it; it cannot turn off a `true` value.
    #[serde(default)]
    pub ir_minimum: bool,

    /// Path to write the file report to, relative to the project root.
    ///
    /// It applies only when exactly one file report (`lcov`, `attribution` or `gaps`) is
    /// requested; with several, it is ignored with a warning and each report uses its default
    /// file name. When unset, the report is written to the project root under its default name.
    /// The `--report-file` flag overrides it.
    #[serde(default)]
    pub report_file: Option<PathBuf>,

    /// Whether to include dependency sources in the coverage report.
    ///
    /// Sources under library directories (`libs`) are excluded by default. The `--include-libs`
    /// flag also enables this; it cannot turn off a `true` value.
    #[serde(default)]
    pub include_libs: bool,

    /// Whether to exclude test sources from the coverage report.
    ///
    /// The `--exclude-tests` flag also enables this; it cannot turn off a `true` value.
    #[serde(default)]
    pub exclude_tests: bool,

    /// Glob patterns of source files to exclude from the coverage report.
    ///
    /// Patterns are matched against paths relative to the project root, with `**`, `*`, `?` and
    /// character classes, and a file is skipped if any pattern matches. There is no flag for this
    /// setting; it applies in addition to `no_match_coverage` and `--no-match-coverage`.
    ///
    /// ```toml
    /// [profile.default.coverage]
    /// skip_files = ["test/**", "script/**", "src/mocks/**"]
    /// ```
    #[serde(default)]
    pub skip_files: Vec<String>,
}

impl Default for CoverageConfig {
    fn default() -> Self {
        Self {
            report: default_report_kinds(),
            lcov_version: default_lcov_version(),
            ir_minimum: false,
            report_file: None,
            include_libs: false,
            exclude_tests: false,
            skip_files: Vec::new(),
        }
    }
}

fn default_report_kinds() -> Vec<CoverageReportKind> {
    vec![CoverageReportKind::Summary]
}

const fn default_lcov_version() -> Version {
    Version::new(1, 0, 0)
}

fn deserialize_lcov_version<'de, D>(deserializer: D) -> Result<Version, D::Error>
where
    D: Deserializer<'de>,
{
    let version = String::deserialize(deserializer)?;
    parse_lcov_version(&version).map_err(serde::de::Error::custom)
}

pub fn parse_lcov_version(s: &str) -> Result<Version, String> {
    let vr = VersionReq::parse(&format!("={s}")).map_err(|e| e.to_string())?;
    let [c] = &vr.comparators[..] else {
        return Err("invalid version".to_string());
    };
    if c.op != semver::Op::Exact {
        return Err("invalid version".to_string());
    }
    if !c.pre.is_empty() {
        return Err("pre-releases are not supported".to_string());
    }
    Ok(Version::new(c.major, c.minor.unwrap_or(0), c.patch.unwrap_or(0)))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_matches_cli_defaults() {
        let cfg = CoverageConfig::default();
        assert_eq!(cfg.report, vec![CoverageReportKind::Summary]);
        assert_eq!(cfg.lcov_version, default_lcov_version());
        assert!(!cfg.ir_minimum);
        assert!(cfg.report_file.is_none());
        assert!(!cfg.include_libs);
        assert!(!cfg.exclude_tests);
        assert!(cfg.skip_files.is_empty());
    }

    #[test]
    fn deserialize_from_toml() {
        let toml = r#"
            report = ["summary", "lcov"]
            lcov_version = "2.2.0"
            ir_minimum = true
            report_file = "out/lcov.info"
            include_libs = true
            exclude_tests = true
            skip_files = ["test/**", "src/mocks/**"]
        "#;
        let cfg: CoverageConfig = toml::from_str(toml).unwrap();
        assert_eq!(cfg.report, vec![CoverageReportKind::Summary, CoverageReportKind::Lcov]);
        assert_eq!(cfg.lcov_version, Version::new(2, 2, 0));
        assert!(cfg.ir_minimum);
        assert_eq!(cfg.report_file.as_deref(), Some(std::path::Path::new("out/lcov.info")));
        assert!(cfg.include_libs);
        assert!(cfg.exclude_tests);
        assert_eq!(cfg.skip_files, vec!["test/**".to_string(), "src/mocks/**".to_string()]);
    }

    #[test]
    fn deserialize_partial_uses_defaults() {
        let toml = r#"skip_files = ["src/mocks/**"]"#;
        let cfg: CoverageConfig = toml::from_str(toml).unwrap();
        // Defaulted fields keep their default values.
        assert_eq!(cfg.report, vec![CoverageReportKind::Summary]);
        assert_eq!(cfg.lcov_version, default_lcov_version());
        assert!(!cfg.ir_minimum);
        // Set field came through.
        assert_eq!(cfg.skip_files, vec!["src/mocks/**".to_string()]);
    }

    #[test]
    fn deserialize_lcov_version_accepts_cli_formats() {
        for (input, expected) in [
            ("0", Version::new(0, 0, 0)),
            ("1", default_lcov_version()),
            ("1.0", default_lcov_version()),
            ("1.1", Version::new(1, 1, 0)),
            ("2", Version::new(2, 0, 0)),
            ("2.2", Version::new(2, 2, 0)),
        ] {
            let cfg: CoverageConfig =
                toml::from_str(&format!(r#"lcov_version = "{input}""#)).unwrap();
            assert_eq!(cfg.lcov_version, expected);
        }
    }
}
